"""Reusable conversions for Meridian CRM legacy storage conventions."""

from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import re

_LEGACY_NULL_DATE = "00000000"
_LEGACY_DATE_RE = re.compile(r"^\d{8}$")
_ISO_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving null semantics."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == _LEGACY_NULL_DATE:
        return None

    if not _LEGACY_DATE_RE.fullmatch(yyyymmdd):
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    try:
        parsed = date(int(yyyymmdd[:4]), int(yyyymmdd[4:6]), int(yyyymmdd[6:8]))
    except ValueError as exc:
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}") from exc

    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD null-sentinel format."""
    if iso is None or iso == "":
        return _LEGACY_NULL_DATE

    if not _ISO_DATE_RE.fullmatch(iso):
        raise ValueError(f"invalid ISO date: {iso!r}")

    try:
        parsed = date.fromisoformat(iso)
    except ValueError as exc:
        raise ValueError(f"invalid ISO date: {iso!r}") from exc

    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N character convention to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units using half-up rounding."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency.strip().upper()
    exponent = 0 if currency_code == "JPY" else 2
    multiplier = Decimal(10) ** exponent

    decimal_amount = Decimal(str(amount))
    return int((decimal_amount * multiplier).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
